// @ts-nocheck
// ===== ไล่เช็ค Tag บนจอ HMI Extruder03 (อ่านอย่างเดียว ไม่เขียนค่า) =====
// อ่าน PLC Omron NJ ด้วย FINS UDP -> แสดงแต่ละ Tag หลายรูปแบบ ให้เทียบกับตัวเลขบนจอ HMI
const HOST = "192.168.250.1", DA1 = 1, SA1 = 50;     // SA1 = เลขท้าย IP กล่อง (192.168.250.50)
const SWAP = true;                                    // NJ เก็บ STRING byte ต่ำก่อน

// Tag จากหน้าจอ HMI (DMxxxxx = D ใน PLC)
const TAGS = [
    { name: "VALVE SETTING",          d: 100 },
    { name: "CUTTER SPEED",           d: 102 },
    { name: "TEMP.",                  d: 104 },
    { name: "WEIGHT (หัวตาราง)",       d: 106 },
    { name: "THROTTLE PRESSURE",      d: 108 },
    { name: "FINISHED QTY (Batch)",   d: 160 },
    { name: "EXPECT COMPLETE TIME (Min)", d: 170 },
    { name: "TOTAL QTY (ช่องเขียว)",   d: 420 },
    { name: "QTY SETUP (ช่องเขียว)",   d: 430 },
    { name: "TOTAL QTY (ช่องชมพู)",    d: 442 },
    { name: "QTY SETUP (ช่องชมพู)",    d: 452 },
    { name: "REAL WEIGHT (g) ข้อความ", d: 554, str: 6 }
];
// ช่วงที่อ่าน (อ่านทีละก้อน ไม่กี่ครั้ง -> PLC/HMI ไม่หนัก)
const BLOCKS = [[0, 200], [400, 60], [540, 40]];

let S = context.get("S");
if (!S) {
    const sock = dgram.createSocket("udp4");
    S = { sock, pending: null, sid: 0 };
    sock.on("message", r => { if (S.pending && r.length >= 14 && r[9] === S.sid) S.pending(null, r); });
    sock.on("error", e => S.pending && S.pending("socket " + e.code));
    sock.bind(0);
    context.set("S", S);
}
if (context.get("busy")) return null;
context.set("busy", true);

function readBlock(start, count) {
    return new Promise(res => {
        S.sid = (S.sid + 1) & 0xFF;
        const req = Buffer.from([0x80, 0, 0x02, 0, DA1, 0, 0, SA1, 0, S.sid, 0x01, 0x01, 0x82,
            (start >> 8) & 0xFF, start & 0xFF, 0, (count >> 8) & 0xFF, count & 0xFF]);
        const t = setTimeout(() => S.pending && S.pending("timeout"), 1000);
        S.pending = (err, r) => {
            clearTimeout(t); S.pending = null;
            if (err) return res({ err });
            const ec = r.readUInt16BE(12);
            if (ec !== 0 && ec !== 0x0040) return res({ err: "end code 0x" + ec.toString(16) });
            const w = []; for (let k = 0; k < count; k++) w.push(r.readUInt16BE(14 + k * 2));
            res({ w });
        };
        S.sock.send(req, 9600, HOST, e => { if (e && S.pending) S.pending("send " + e.code); });
    });
}
const ch = c => (c >= 32 && c < 127 ? String.fromCharCode(c) : "·");
const wstr = w => { let a = (w >> 8) & 0xFF, b = w & 0xFF; if (SWAP) [a, b] = [b, a]; return ch(a) + ch(b); };

(async () => {
    const mem = {}, errs = [];
    for (const [s, n] of BLOCKS) {
        const r = await readBlock(s, n);
        if (r.err) errs.push("D" + s + "-" + (s + n - 1) + ": " + r.err);
        else r.w.forEach((v, k) => mem[s + k] = v);
    }
    context.set("busy", false);
    if (errs.length && !Object.keys(mem).length) {
        node.status({ fill: "red", shape: "ring", text: errs[0] });
        node.send([{ payload: { error: errs } }, null]);
        return;
    }
    const W = d => mem[d];
    const out = {};
    for (const t of TAGS) {
        const lo = W(t.d), hi = W(t.d + 1);
        if (lo === undefined) { out[t.name + "  [D" + t.d + "]"] = "อ่านไม่ได้"; continue; }
        if (t.str) {
            let s = ""; for (let k = 0; k < Math.ceil(t.str / 2) + 4; k++) s += wstr(W(t.d + k) || 0);
            out[t.name + "  [D" + t.d + "]"] = { "ข้อความ": s.replace(/·/g, " ").trim(), "ข้อความ (D550 ทั้งก้อน)": Array.from({ length: 8 }, (_, k) => wstr(W(550 + k) || 0)).join("").replace(/·/g, " ").trim() };
            continue;
        }
        const b = Buffer.alloc(4); b.writeUInt16BE(hi || 0, 0); b.writeUInt16BE(lo, 2);
        const i16 = lo > 32767 ? lo - 65536 : lo, i32 = b.readInt32BE(0), f = b.readFloatBE(0);
        out[t.name + "  [D" + t.d + "]"] = {
            "INT16": i16, "INT16 /10": i16 / 10,
            ["DINT32 (D" + t.d + "-" + (t.d + 1) + ")"]: i32, "DINT32 /10": i32 / 10,
            "REAL": Math.abs(f) < 1e9 && Math.abs(f) > 1e-6 ? Math.round(f * 1000) / 1000 : (f === 0 ? 0 : "-"),
            "raw": "0x" + lo.toString(16).padStart(4, "0") + " 0x" + (hi || 0).toString(16).padStart(4, "0")
        };
    }
    // หา PRODUCTION NAME: ไล่หาข้อความ ASCII (>= 4 ตัว) ใน D0–D199
    const strings = {};
    let run = "", from = null;
    for (let d = 0; d <= 200; d++) {
        const s = d < 200 && W(d) !== undefined ? wstr(W(d)) : "··";
        if (s !== "··" && s.replace(/·/g, "").length > 0 && /[A-Za-z0-9]/.test(s)) { if (from === null) from = d; run += s; }
        else { const txt = run.replace(/·/g, "").trim(); if (from !== null && txt.length >= 4) strings["D" + from + "-D" + (d - 1)] = txt; run = ""; from = null; }
    }
    node.status({ fill: errs.length ? "yellow" : "green", shape: "dot", text: "อ่านแล้ว " + new Date().toLocaleTimeString("th-TH") + (errs.length ? " · บางช่วงอ่านไม่ได้" : "") });
    node.send([{ payload: out }, { payload: { "ข้อความที่เจอใน D0–D199 (หา PRODUCTION NAME)": strings, error: errs.length ? errs : undefined } }]);
})();
return null;
